import time
import numpy as np
from scipy.sparse.linalg import eigs, aslinearoperator
from scipy.sparse.linalg._eigen.arpack.arpack import _UnsymmetricArpackParams
from reference import Task

task = Task()
probs = [task.generate_problem(n=300, random_seed=s) for s in range(6)]

def ref_solve(p):
    A = p["matrix"]; k=p["k"]; N=A.shape[0]
    v0 = np.ones(N, dtype=A.dtype)
    return eigs(A, k=k, v0=v0, maxiter=N*200, ncv=max(2*k+1, 20))

def make(p, matvec_kind):
    A = p["matrix"]; k=p["k"]; N=A.shape[0]
    ncv = max(2*k+1, 20)
    v0 = np.ones(N, dtype=A.dtype)
    if matvec_kind == "dot":
        matvec = A.dot
    elif matvec_kind == "matmul_vector":
        matvec = A._matmul_vector
    elif matvec_kind == "aslin":
        matvec = aslinearoperator(A).matvec
    params = _UnsymmetricArpackParams(N, k, A.dtype.char, matvec, 1,
                                      None, None, None,
                                      ncv, v0, N*200, "LM", 0, None)
    while not params.converged:
        params.iterate()
    return params.extract(True)

p = probs[0]
ev1, vec1 = ref_solve(p)
for kind in ["dot", "matmul_vector", "aslin"]:
    ev, vec = make(p, kind)
    print(kind, "maxdiff", np.max(np.abs(vec1-vec)), "evaldiff", np.max(np.abs(ev1-ev)))

def timeit(fn, reps=1):
    fn(probs[0])
    t0 = time.perf_counter()
    for _ in range(reps):
        for p in probs:
            fn(p)
    return (time.perf_counter()-t0)/(reps*len(probs))*1000

print("ref", timeit(ref_solve), "ms")
for kind in ["dot", "matmul_vector", "aslin"]:
    print(kind, timeit(lambda p, kind=kind: make(p, kind)), "ms")
