{"command":"python3 - << 'EOF'
import time
import numpy as np
from scipy.sparse.linalg._eigen.arpack import arpack as ar
from scipy.sparse.linalg._eigen.arpack.arpack import _UnsymmetricArpackParams
from reference import Task

# monkeypatch iterate to time fortran vs python
orig = ar._UnsymmetricArpackParams.iterate
stats = {"fortran": 0.0, "py": 0.0, "calls": 0}

def timed_iterate(self):
    t0 = time.perf_counter()
    if self.tp in 'fd':
        self._arpack_solver(
            self.arpack_dict, self.resid, self.v, self.ipntr, self.workd,
            self.workl
        )
    else:
        self._arpack_solver(
            self.arpack_dict, self.resid, self.v, self.ipntr, self.workd,
            self.workl, self.rwork
        )
    t1 = time.perf_counter()
    stats["fortran"] += t1 - t0
    stats["calls"] += 1

    xslice = slice(self.ipntr[0], self.ipntr[0] + self.n)
    yslice = slice(self.ipntr[1], self.ipntr[1] + self.n)

    if self.arpack_dict['ido'] == 1:
        if self.mode in (1, 2):
            self.workd[yslice] = self.OP(self.workd[xslice])
        else:
            Bxslice = slice(self.ipntr[2], self.ipntr[2] + self.n)
            self.workd[yslice] = self.OPa(self.workd[Bxslice])
    elif self.arpack_dict['ido'] == 2:
        self.workd[yslice] = self.B(self.workd[xslice])
    elif self.arpack_dict['ido'] == 3:
        raise ValueError("ARPACK requested user shifts. Assure ISHIFT==0")
    elif self.arpack_dict['ido'] == 4:
        if self.tp in 'fd':
            self.resid[:] = self.rng.uniform(low=-1.0, high=1.0, size=[self.n]).astype(self.tp)
        else:
            self.resid[:] = self.rng.uniform(low=-1.0, high=1.0, size=[self.n, 2]).view(np.complex128).astype(self.tp).ravel()
    elif self.arpack_dict['ido'] == 5:
        self.workd[yslice] = self.OP(self.workd[xslice])
    else:
        self.converged = True
        if self.arpack_dict['info'] == 0:
            pass
        elif self.arpack_dict['info'] == 1:
            self._raise_no_convergence()
        else:
            raise ar.ArpackError(info=self.arpack_dict['info'], infodict=self.iterate_infodict)
    stats["py"] += time.perf_counter() - t1

ar._UnsymmetricArpackParams.iterate = timed_iterate

task = Task()
probs = [task.generate_problem(n=300, random_seed=s) for s in range(5)]

def solve(p):
    A = p["matrix"]; k=p["k"]; N=A.shape[0]
    v0 = np.ones(N, dtype=A.dtype)
    matvec = A._matmul_vector
    params = _UnsymmetricArpackParams(N, k, A.dtype.char, matvec, 1,
                                      None, None, None,
                                      20, v0, N*200, "LM", 0, None)
    while not params.converged:
        params.iterate()
    return params.extract(True)

# warmup
solve(probs[0])
stats["fortran"]=stats["py"]=0.0; stats["calls"]=0
t0 = time.perf_counter()
for p in probs:
    solve(p)
t1 = time.perf_counter()
total = t1-t0
print(f"total {total:.3f}s  per {total/len(probs)*1000:.1f} ms")
print(f"fortran {stats['fortran']:.3f}s ({100*stats['fortran']/total:.1f}%)")
print(f"py matvec+loop {stats['py']:.3f}s ({100*stats['py']/total:.1f}%)")
print(f"calls {stats['calls']}  per solve {stats['calls']/len(probs):.0f}")
print(f"other (setup/extract) {total-stats['fortran']-stats['py']:.3f}s")
EOF"}

