#include <stdint.h>
#include <string.h>
#include <stdio.h>

/* ARNAUD double-precision non-symmetric reverse communication.
 * state is the SciPy arnaud_state_d struct (240 bytes on this build):
 *   double tol, getv0_rnorm0, aitr_betaj, aitr_rnorm1, aitr_wnorm, aup2_rnorm;
 *   int32 fields follow, 8-byte aligned.
 */
typedef struct {
    double tol;
    double getv0_rnorm0;
    double aitr_betaj;
    double aitr_rnorm1;
    double aitr_wnorm;
    double aup2_rnorm;
    int32_t ido;
    int32_t which;
    int32_t bmat;
    int32_t info;
    int32_t iter;
    int32_t maxiter;
    int32_t mode;
    int32_t n;
    int32_t nconv;
    int32_t ncv;
    int32_t nev;
    int32_t np;
    int32_t shift;
    int32_t getv0_first;
    int32_t getv0_iter;
    int32_t getv0_itry;
    int32_t getv0_orth;
    int32_t aitr_iter;
    int32_t aitr_j;
    int32_t aitr_orth1;
    int32_t aitr_orth2;
    int32_t aitr_restart;
    int32_t aitr_step3;
    int32_t aitr_step4;
    int32_t aitr_ierr;
    int32_t aup2_initv;
    int32_t aup2_iter;
    int32_t aup2_getv0;
    int32_t aup2_cnorm;
    int32_t aup2_kplusp;
    int32_t aup2_nev;
    int32_t aup2_nev0;
    int32_t aup2_np0;
    int32_t aup2_numcnv;
    int32_t aup2_update;
    int32_t aup2_ushift;
    int32_t _pad;
} arnaud_state_d;

extern void ARNAUD_dnaupd(arnaud_state_d *state, double *resid, double *v,
                           int32_t *ipntr, double *workd, double *workl, int32_t lworkl);

/* mode-1 standard eigenproblem, bmat = identity.
 * Returns 0 on convergence (info==0), 1 on no convergence, <0 on ARPACK error.
 * On return, *niter is the number of reverse-communication steps.
 */
int fast_dnaupd_mode1(arnaud_state_d *state,
                      double *resid, double *v, int32_t *ipntr,
                      double *workd, double *workl, int32_t lworkl,
                      const int32_t *indptr, const int32_t *indices,
                      const double *data) {
    const int32_t n = state->n;
    int guard = 0;
    const int guard_max = (int)state->maxiter * (int)state->ncv * 4 + 1000;
    if (guard_max < 100000) {
        /* keep a generous cap even if maxiter is small */
    }
    int cap = guard_max > 2000000 ? 2000000 : (guard_max < 100000 ? 100000 : guard_max);

    while (1) {
        ARNAUD_dnaupd(state, resid, v, ipntr, workd, workl, lworkl);
        int32_t ido = state->ido;
        if (ido == 1 || ido == 5) {
            /* y = A x, pointers are 1-based into workd */
            int32_t x0 = ipntr[0] - 1;
            int32_t y0 = ipntr[1] - 1;
            const double *x = workd + x0;
            double *y = workd + y0;
            for (int32_t i = 0; i < n; i++) {
                double s = 0.0;
                int32_t a = indptr[i];
                int32_t b = indptr[i + 1];
                for (int32_t j = a; j < b; j++) {
                    s += data[j] * x[indices[j]];
                }
                y[i] = s;
            }
        } else if (ido == 2) {
            int32_t x0 = ipntr[0] - 1;
            int32_t y0 = ipntr[1] - 1;
            memcpy(workd + y0, workd + x0, (size_t)n * sizeof(double));
        } else if (ido == 4) {
            /* should not happen when info was 1 (user supplied v0) */
            return -100;
        } else if (ido == 3) {
            return -101;
        } else {
            /* done */
            if (state->info == 0) return 0;
            if (state->info == 1) return 1;
            return -(int)state->info;
        }
        if (++guard > cap) return -102;
    }
}
EOF
cc -O3 -shared -fPIC -o fast_eigs.so fast_eigs.c && echo BUILT && ls -la fast_eigs.so"}

