                        import re
                        m = re.search(r'(-?0x[0-9a-f]+)\(%r14\)', lj)
                        if m:
                            off = int(m.group(1), 16)
                        else:
                            m = re.search(r'(-?\d+)\(%r14\)', lj)
                            if m:
                                off = int(m.group(1))
                    kind = "d" if "movsd" in lj else "i"
                    break
            if 'literal pool for: "' in lj and j > i+1:
                break
        fields.append((name, off, kind))
