from scipy.sparse.linalg import eigs
from reference import Task

task = Task()
probs = [task.generate_problem(n=300, random_seed=s) for s in range(15)]

def run(p, ncv, tol=0, maxiter=None):
    A = p["matrix"]; N=A.shape[0]; k=5
    if maxiter is None:
        maxiter = N*200
    v0 = np.ones(N)
    return eigs(A, k=k, v0=v0, ncv=ncv, tol=tol, maxiter=maxiter)

def ref(p):
    return run(p, 20, 0, p["matrix"].shape[0]*200)

exps = []
for p in probs:
    ev, vec = ref(p)
    pairs = sorted(zip(ev, vec.T), key=lambda x: -abs(x[0]))
    exps.append(pairs)

def score(ncv, tol=0, maxiter=None):
    fails = 0
    t0 = time.perf_counter()
    for p, exp in zip(probs, exps):
        try:
            ev, vec = run(p, ncv, tol, maxiter if maxiter else p["matrix"].shape[0]*200)
        except Exception:
            fails += 1
            continue
        pairs = sorted(zip(ev, vec.T), key=lambda x: -abs(x[0]))
        for (e1,v1),(e2,v2) in zip(exp, pairs):
            sim = abs(np.vdot(v1, v2))
            if sim < 1-1e-8 or abs(e1-e2) > 1e-8:
