extern void ARNAUD_dnaupd(arnaud_state_d *state, double *resid, double *v,
                           int32_t n, int32_t *ipntr, double *workd, double *workl);

/* (state, rvec, howmny, select, dr, di, Z, ldz, sigmar, sigmai, workev,
 *  bmat-data?, resid, V, ldv, ipntr, workd, workl)
 * Recovered from dneupd_wrap. ldz and ldv are the leading dims (by value, but
 * the wrapper pushes the stride qwords). We pass n for both.
 */
extern void ARNAUD_dneupd(arnaud_state_d *state, int32_t rvec, int32_t howmny,
                          int32_t *select, double *dr, double *di, double *z,
                          double sigmar, double sigmai, double *workev,
                          double *resid, double *v, int32_t *ipntr,
                          double *workd, double *workl, int64_t ldz, int64_t ldv);

static inline void csr_matvec(int32_t n, const int32_t *indptr,
                              const int32_t *indices, const double *data,
                              const double *x, double *y) {
    for (int32_t i = 0; i < n; ++i) {
        const int32_t a = indptr[i];
        const int32_t b = indptr[i + 1];
        double s0 = 0.0, s1 = 0.0, s2 = 0.0, s3 = 0.0;
        int32_t j = a;
        for (; j + 3 < b; j += 4) {
            s0 += data[j] * x[indices[j]];
            s1 += data[j + 1] * x[indices[j + 1]];
            s2 += data[j + 2] * x[indices[j + 2]];
            s3 += data[j + 3] * x[indices[j + 3]];
        }
        double s = (s0 + s1) + (s2 + s3);
        for (; j < b; ++j)
            s += data[j] * x[indices[j]];
        y[i] = s;
    }
}

/* Returns 0 on success. On success, dr/di/z hold the raw ARPACK extract
 * (k+1 values, n*(k+1) vector columns, column-major). Caller builds complex
 * pairs and selects the k wanted ones exactly as SciPy does.
 */
int fast_eigs_raw(int32_t n, int32_t k, int32_t ncv, int32_t maxiter,
                  const int32_t *indptr, const int32_t *indices, const double *data,
                  double *resid, double *v, int32_t *ipntr, double *workd, double *workl,
                  double *dr, double *di, double *z, double *workev, int32_t *select,
                  int32_t *nreturned, int32_t *info_out) {
    arnaud_state_d st;
    memset(&st, 0, sizeof(st));
    st.which = 0;          /* LM */
    st.info = 1;           /* user-supplied residual */
    st.bmat = 0;           /* identity */
    st.mode = 1;
    st.n = n;
    st.ncv = ncv;
    st.nev = k;
    st.shift = 1;
    st.maxiter = maxiter;

    int guard = 0;
    while (1) {
        ARNAUD_dnaupd(&st, resid, v, n, ipntr, workd, workl);
        int32_t ido = st.ido;
        if (ido == 1 || ido == 5) {
            csr_matvec(n, indptr, indices, data, workd + ipntr[0], workd + ipntr[1]);
        } else if (ido == 2) {
            memcpy(workd + ipntr[1], workd + ipntr[0], (size_t)n * sizeof(double));
        } else if (ido == 3 || ido == 4) {
            *info_out = st.info;
            return -100 - ido;
        } else {
            break;
        }
        if (++guard > 8000000) {
            *info_out = st.info;
            return -102;
        }
    }
    if (st.info != 0) {
        *info_out = st.info;
        return st.info == 1 ? 1 : -st.info;
    }

    /* extract, matching _UnsymmetricArpackParams.extract */
    st.info = 0;
    ARNAUD_dneupd(&st, 1 /* rvec */, 0 /* howmny A */, select, dr, di, z,
                  0.0, 0.0, workev, resid, v, ipntr, workd, workl,
                  (int64_t)n, (int64_t)n);
    if (st.info != 0) {
        *info_out = st.info;
        return -200 - st.info;
    }
    *nreturned = st.nconv;
    *info_out = 0;
    return 0;
}
