static inline void csr_matvec(int32_t n, const int32_t *indptr,
                              const int32_t *indices, const double *data,
                              const double *x, double *y) {
    int32_t i = 0;
    for (; i < n; ++i) {
        const int32_t a = indptr[i];
        const int32_t b = indptr[i + 1];
        double s0 = 0.0, s1 = 0.0, s2 = 0.0, s3 = 0.0;
        int32_t j = a;
        for (; j + 3 < b; j += 4) {
            s0 += data[j] * x[indices[j]];
            s1 += data[j + 1] * x[indices[j + 1]];
            s2 += data[j + 2] * x[indices[j + 2]];
            s3 += data[j + 3] * x[indices[j + 3]];
        }
        double s = (s0 + s1) + (s2 + s3);
        for (; j < b; ++j)
            s += data[j] * x[indices[j]];
        y[i] = s;
    }
}

/* Fills the state struct (out) and the workspace arrays. Returns 0 on
 * convergence (info==0). ipntr is 0-based, matching SciPy's wrapper.
 */
int fast_dnaupd_mode1(arnaud_state_d *state,
                      double *resid, double *v, int32_t *ipntr,
                      double *workd, double *workl,
                      const int32_t *indptr, const int32_t *indices,
                      const double *data) {
    const int32_t n = state->n;
    int guard = 0;
    while (1) {
        ARNAUD_dnaupd(state, resid, v, n, ipntr, workd, workl);
        int32_t ido = state->ido;
        if (ido == 1 || ido == 5) {
            csr_matvec(n, indptr, indices, data, workd + ipntr[0], workd + ipntr[1]);
        } else if (ido == 2) {
            memcpy(workd + ipntr[1], workd + ipntr[0], (size_t)n * sizeof(double));
        } else if (ido == 3 || ido == 4) {
            return -100 - ido;
        } else {
            if (state->info == 0) return 0;
            if (state->info == 1) return 1;
            return -((int)state->info);
        }
        if (++guard > 8000000) return -102;
    }
}
